
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_perdew_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_perdew", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.393993599263278e+01, 9.028640017569698e+01, 8.529102795032105e+01, 7.861057676484108e+01, 6.995539587710651e+01, 5.923784641275192e+01, 4.679297465983765e+01, 3.359709412869403e+01, 2.127606054804558e+01, 1.159348865023174e+01, 5.333631366935109e+00, 2.538010874924273e+00, 1.906723597006001e+00, 1.264827807163172e+00, 6.461811421051369e-01, 2.673947811193191e-01, 1.165398735393708e-01, 7.637793006994223e-02, 6.738199011036276e-02, 6.394776400914477e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


